solution.solution.cpp:
#include <cctype>
#include <optional>
#include <string>
#include <utility>
#include <vector>

struct Head
{
    std::string method, target, version;
    std::vector<std::pair<std::string, std::string>> headers;
};

enum class BodyKind { None, Length, Chunked, Invalid };
struct Body { BodyKind kind; std::size_t length; };

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::optional<Head> parseHead(const std::string& head)
{
    std::vector<std::string> lines;
    std::size_t at{ 0 };
    while (true)
    {
        const std::size_t end{ head.find("\r\n", at) };
        lines.push_back(head.substr(at, end == std::string::npos ? std::string::npos : end - at));
        if (end == std::string::npos) break;
        at = end + 2;
    }
    Head h;
    const std::string& first{ lines[0] };
    const std::size_t a{ first.find(' ') };
    const std::size_t b{ a == std::string::npos ? a : first.find(' ', a + 1) };
    if (a == std::string::npos || b == std::string::npos || first.find(' ', b + 1) != std::string::npos) return std::nullopt;
    h.method = first.substr(0, a);
    h.target = first.substr(a + 1, b - a - 1);
    h.version = first.substr(b + 1);
    if (h.method.empty() || h.target.empty() || h.version.rfind("HTTP/", 0) != 0) return std::nullopt;
    for (std::size_t i{ 1 }; i < lines.size(); ++i)
    {
        const std::string& line{ lines[i] };
        const std::size_t colon{ line.find(':') };
        if (colon == std::string::npos || colon == 0) return std::nullopt;
        const std::string name{ line.substr(0, colon) };
        if (name.find_first_of(" \t") != std::string::npos) return std::nullopt;
        std::string value{ line.substr(colon + 1) };
        const std::size_t s{ value.find_first_not_of(" \t") };
        const std::size_t e{ value.find_last_not_of(" \t") };
        value = s == std::string::npos ? "" : value.substr(s, e - s + 1);
        h.headers.push_back({ lower(name), value });
    }
    return h;
}

std::vector<std::string> headerValues(const Head& h, const std::string& name)
{
    std::vector<std::string> out;
    const std::string key{ lower(name) };
    for (const auto& [n, v] : h.headers) if (n == key) out.push_back(v);
    return out;
}

Body requestBody(const Head& h)
{
    const auto te{ headerValues(h, "transfer-encoding") };
    const auto cl{ headerValues(h, "content-length") };
    if (!te.empty() && !cl.empty()) return { BodyKind::Invalid, 0 };
    if (!te.empty())
    {
        if (te.size() == 1 && lower(te[0]) == "chunked") return { BodyKind::Chunked, 0 };
        return { BodyKind::Invalid, 0 };
    }
    if (cl.empty()) return { BodyKind::None, 0 };
    for (const std::string& v : cl) if (v != cl[0]) return { BodyKind::Invalid, 0 };
    const std::string& v{ cl[0] };
    if (v.empty() || v.size() > 15) return { BodyKind::Invalid, 0 };
    for (char c : v) if (!std::isdigit(static_cast<unsigned char>(c))) return { BodyKind::Invalid, 0 };
    return { BodyKind::Length, static_cast<std::size_t>(std::stoull(v)) };
}

unitTests:
TEST("a request head") {
    const auto h{ parseHead("POST /api/progress HTTP/1.1\r\nHost: xenon.justloofy.dev\r\nContent-Type:application/json \r\nContent-Length:   42") };
    CHECK(h.has_value());
    if (!h) return;
    CHECK_EQ(h->method, std::string("POST"));
    CHECK_EQ(h->target, std::string("/api/progress"));
    CHECK_EQ(h->headers.size(), 3u);
    CHECK_EQ(h->headers[1].first, std::string("content-type"));
    CHECK_EQ(h->headers[1].second, std::string("application/json"));
    CHECK_EQ(headerValues(*h, "HOST"), std::vector<std::string>{ "xenon.justloofy.dev" });
    const Body b{ requestBody(*h) };
    CHECK(b.kind == BodyKind::Length);
    CHECK_EQ(b.length, 42u);
}
TEST("malformed heads") {
    CHECK(!parseHead("GET /\r\nHost: x").has_value());
    CHECK(!parseHead("GET  / HTTP/1.1").has_value());
    CHECK(!parseHead("GET / HTTP/1.1 extra").has_value());
    CHECK(!parseHead("GET / FTP/1.0").has_value());
    CHECK(!parseHead("GET / HTTP/1.1\r\nNo colon here").has_value());
    CHECK(!parseHead("GET / HTTP/1.1\r\nBad Name: x").has_value());
    CHECK(!parseHead("GET / HTTP/1.1\r\n: empty").has_value());
    const auto ok{ parseHead("GET / HTTP/1.1") };
    CHECK(ok.has_value());
    if (ok) CHECK(requestBody(*ok).kind == BodyKind::None);
}
TEST("body rules") {
    const auto chunked{ parseHead("POST / HTTP/1.1\r\nTransfer-Encoding: Chunked") };
    CHECK(requestBody(*chunked).kind == BodyKind::Chunked);
    const auto both{ parseHead("POST / HTTP/1.1\r\nContent-Length: 5\r\nTransfer-Encoding: chunked") };
    CHECK(requestBody(*both).kind == BodyKind::Invalid);
    const auto twoLengths{ parseHead("POST / HTTP/1.1\r\nContent-Length: 5\r\nContent-Length: 6") };
    CHECK(requestBody(*twoLengths).kind == BodyKind::Invalid);
    const auto sameTwice{ parseHead("POST / HTTP/1.1\r\nContent-Length: 5\r\ncontent-length: 5") };
    CHECK(requestBody(*sameTwice).kind == BodyKind::Length);
    const auto negative{ parseHead("POST / HTTP/1.1\r\nContent-Length: -1") };
    CHECK(requestBody(*negative).kind == BodyKind::Invalid);
    const auto gzip{ parseHead("POST / HTTP/1.1\r\nTransfer-Encoding: gzip, chunked") };
    CHECK(requestBody(*gzip).kind == BodyKind::Invalid);
    const auto zero{ parseHead("POST / HTTP/1.1\r\nContent-Length: 0") };
    CHECK(requestBody(*zero).kind == BodyKind::Length);
}

